public class Ord1 {
    static String log = "";
    static void f(int n) {
        try {
            log += "t" + n;
            if (n == 0) throw new RuntimeException();
            f(n - 1);
        } finally {
            log += "f" + n;
        }
    }
    public static void main(String[] args) {
        try {
            f(2);
        } catch (RuntimeException e) {
            log += "c";
        }
        System.out.println(log);
    }
}

