public class Res {
    static String result = "";
    static void process(int[] arr, int idx) {
        try {
            result += arr[idx];
        } catch (ArrayIndexOutOfBoundsException e) {
            result += "!";
        } catch (NullPointerException e) {
            result += "?";
        } finally {
            result += ".";
        }
    }
    public static void main(String[] args) {
        process(new int[]{7}, 0);
        process(new int[]{7}, 5);
        process(null, 0);
        System.out.println(result);
    }
}

