class AppEx extends RuntimeException {
    final int code;
    AppEx(int code, String msg) { super(msg); this.code = code; }
}
public class Codes {
    static void check(int v) {
        if (v < 0) throw new AppEx(400, "ujemna");
        if (v > 100) throw new AppEx(413, "za duża");
    }
    public static void main(String[] args) {
        int total = 0;
        for (int v : new int[]{-1, 50, 200}) {
            try {
                check(v);
            } catch (AppEx e) {
                total += e.code;
            }
        }
        System.out.println(total);
    }
}

